args.code:
args => {
    int w = (int)(long)args["width"];
    int h = (int)(long)args["height"];
    string style = (string)args["style"];
    string accent = args.ContainsKey("accent_color") ? (string)args["accent_color"] : "#00FF88";
    string text = args.ContainsKey("text") ? (string)args["text"] : "";

    // Parse accent color
    int r = Convert.ToInt32(accent.Substring(1,2), 16);
    int g = Convert.ToInt32(accent.Substring(3,2), 16);
    int b = Convert.ToInt32(accent.Substring(5,2), 16);
    Color accentColor = Color.FromArgb(r, g, b);

    string path = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Desktop), "SparkByte_Wallpaper.png");

    using var bmp = new Bitmap(w, h);
    using var gfx = Graphics.FromImage(bmp);
    gfx.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
    gfx.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;

    Random rand = new Random();

    switch (style)
    {
        case "cyberpunk":
            // Dark background
            gfx.Clear(Color.FromArgb(10, 10, 30));
            // Grid lines
            using (Pen gridPen = new Pen(Color.FromArgb(40, accentColor)))
            {
                for (int x = 0; x < w; x += 40)
                    gfx.DrawLine(gridPen, x, 0, x, h);
                for (int y = 0; y < h; y += 40)
                    gfx.DrawLine(gridPen, 0, y, w, y);
            }
            // Glowing circles
            for (int i = 0; i < 15; i++)
            {
                int cx = rand.Next(0, w);
                int cy = rand.Next(0, h);
                int rad = rand.Next(20, 120);
                using (var brush = new SolidBrush(Color.FromArgb(30, accentColor)))
                    gfx.FillEllipse(brush, cx - rad, cy - rad, rad * 2, rad * 2);
            }
            // Hexagon-ish shapes
            for (int i = 0; i < 8; i++)
            {
                int cx = rand.Next(0, w);
                int cy = rand.Next(0, h);
                int size = rand.Next(30, 80);
                PointF[] hex = new PointF[6];
                for (int j = 0; j < 6; j++)
                {
                    double angle = j * Math.PI / 3 - Math.PI / 6;
                    hex[j] = new PointF(cx + size * (float)Math.Cos(angle), cy + size * (float)Math.Sin(angle));
                }
                using (var pen = new Pen(Color.FromArgb(100, accentColor), 2))
                    gfx.DrawPolygon(pen, hex);
            }
            break;

        case "minimal":
            gfx.Clear(Color.FromArgb(20, 20, 25));
            // Large accent circle
            using (var brush = new SolidBrush(Color.FromArgb(40, accentColor)))
                gfx.FillEllipse(brush, w / 2 - 200, h / 2 - 200, 400, 400);
            // Thin lines
            using (var pen = new Pen(Color.FromArgb(80, accentColor), 1))
            {
                gfx.DrawLine(pen, 0, h / 2, w, h / 2);
                gfx.DrawLine(pen, w / 2, 0, w / 2, h);
            }
            break;

        case "space":
            gfx.Clear(Color.FromArgb(5, 5, 15));
            // Stars
            for (int i = 0; i < 300; i++)
            {
                int sx = rand.Next(0, w);
                int sy = rand.Next(0, h);
                int size = rand.Next(1, 4);
                int alpha = rand.Next(100, 255);
                using (var brush = new SolidBrush(Color.FromArgb(alpha, 255, 255, 255)))
                    gfx.FillEllipse(brush, sx, sy, size, size);
            }
            // Nebula blobs
            for (int i = 0; i < 5; i++)
            {
                int cx = rand.Next(0, w);
                int cy = rand.Next(0, h);
                int rad = rand.Next(80, 200);
                Color nebColor = i % 2 == 0 ? accentColor : Color.FromArgb(rand.Next(100, 200), rand.Next(50, 150), rand.Next(150, 255));
                using (var brush = new SolidBrush(Color.FromArgb(15, nebColor)))
                    gfx.FillEllipse(brush, cx - rad, cy - rad, rad * 2, rad * 2);
            }
            break;

        case "abstract":
            gfx.Clear(Color.FromArgb(15, 15, 20));
            // Splatter shapes
            for (int i = 0; i < 20; i++)
            {
                int cx = rand.Next(0, w);
                int cy = rand.Next(0, h);
                int rad = rand.Next(30, 150);
                Color splat = Color.FromArgb(rand.Next(20, 60), accentColor);
                using (var brush = new SolidBrush(splat))
                    gfx.FillEllipse(brush, cx - rad, cy - rad, rad * 2, rad * 2);
            }
            // Random curves
            for (int i = 0; i < 10; i++)
            {
                using (var pen = new Pen(Color.FromArgb(80, accentColor), rand.Next(1, 4)))
                {
                    Point p1 = new Point(rand.Next(0, w), rand.Next(0, h));
                    Point p2 = new Point(rand.Next(0, w), rand.Next(0, h));
                    Point c1 = new Point(rand.Next(0, w), rand.Next(0, h));
                    Point c2 = new Point(rand.Next(0, w), rand.Next(0, h));
                    gfx.DrawBezier(pen, p1, c1, c2, p2);
                }
            }
            break;

        case "sparkbyte":
        default:
            // Dark gradient feel
            gfx.Clear(Color.FromArgb(8, 8, 20));
            // SparkByte signature: lightning bolts and sparkles
            for (int i = 0; i < 12; i++)
            {
                int sx = rand.Next(0, w);
                int sy = rand.Next(0, h);
                int len = rand.Next(40, 120);
                using (var pen = new Pen(Color.FromArgb(120, accentColor), 2))
                {
                    Point start = new Point(sx, sy);
                    Point end = new Point(sx + rand.Next(-30, 30), sy + len);
                    Point mid = new Point(sx + rand.Next(-20, 20), sy + len / 3);
                    Point mid2 = new Point(sx + rand.Next(-20, 20), sy + 2 * len / 3);
                    gfx.DrawBezier(pen, start, mid, mid2, end);
                }
            }
            // Sparkle dots
            for (int i = 0; i < 60; i++)
            {
                int sx = rand.Next(0, w);
                int sy = rand.Next(0, h);
                int size = rand.Next(2, 6);
                int alpha = rand.Next(80, 200);
                using (var brush = new SolidBrush(Color.FromArgb(alpha, 255, 255, 255)))
                    gfx.FillEllipse(brush, sx, sy, size, size);
            }
            break;
    }

    // Draw text if provided
    if (!string.IsNullOrEmpty(text))
    {
        float fontSize = Math.Min(w, h) / 20f;
        if (fontSize < 12) fontSize = 12;
        if (fontSize > 80) fontSize = 80;
        using (var font = new Font("Segoe UI", fontSize, FontStyle.Bold))
        using (var brush = new SolidBrush(Color.FromArgb(200, 255, 255, 255)))
        {
            var sf = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
            gfx.DrawString(text, font, brush, w / 2, h / 2 + 10, sf);
            // Shadow
            using (var shadowBrush = new SolidBrush(Color.FromArgb(80, 0, 0, 0)))
                gfx.DrawString(text, font, shadowBrush, w / 2 + 3, h / 2 + 13, sf);
        }
    }

    // Signature
    using (var sigFont = new Font("Segoe UI", 10, FontStyle.Italic))
    using (var sigBrush = new SolidBrush(Color.FromArgb(100, accentColor)))
        gfx.DrawString("✦ SparkByte", sigFont, sigBrush, w - 120, h - 30);

    bmp.Save(path, System.Drawing.Imaging.ImageFormat.Png);

    // Apply as wallpaper via Win32 API
    var psi = new System.Diagnostics.ProcessStartInfo
    {
        FileName = "powershell",
        Arguments = $"-Command \"Add-Type -TypeDefinition @'\\nusing System;\\nusing System.Runtime.InteropServices;\\npublic class WP {{ [DllImport(\\\"user32.dll\\\", CharSet=CharSet.Auto)] public static extern int SystemParametersInfo(int uAction, int uParam, string lpvParam, int fuWinIni); }}'@; [WP]::SystemParametersInfo(20, 0, '{path}', 2)\"",
        WindowStyle = System.Diagnostics.ProcessWindowStyle.Hidden,
        CreateNoWindow = true
    };
    var proc = System.Diagnostics.Process.Start(psi);
    proc.WaitForExit();

    return new Dictionary<string, object?>
    {
        ["path"] = path,
        ["width"] = w,
        ["height"] = h,
        ["style"] = style,
        ["message"] = $"✨ Wallpaper generated and applied! Saved to: {path}"
    };
}
